"use client";

import Link from "next/link";
import { Suspense, useEffect, useMemo, useState } from "react";
import { usePathname, useRouter, useSearchParams } from "next/navigation";
import { StageBadge } from "@/components/StageBadge";
import { StatusBadge } from "@/components/StatusBadge";
import { getRecords } from "@/services/api";
import { Candidate, CandidateStage, CandidateStatus, STAGE_OPTIONS, STATUS_OPTIONS } from "@/types/candidate";

function HomePageContent() {
  const [records, setRecords] = useState<Candidate[]>([]);
  const [searchText, setSearchText] = useState("");
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");

  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();

  const selectedStatus = (searchParams.get("status") as CandidateStatus | null) ?? "";
  const selectedStage = (searchParams.get("stage") as CandidateStage | null) ?? "";
  const created = searchParams.get("created") === "1";

  useEffect(() => {
    async function loadRecords() {
      setIsLoading(true);
      setError("");

      try {
        const data = await getRecords();
        setRecords(data);
      } catch (loadError) {
        setError(loadError instanceof Error ? loadError.message : "No se pudieron cargar las candidaturas.");
      } finally {
        setIsLoading(false);
      }
    }

    void loadRecords();
  }, []);

  function updateQueryParam(name: "status" | "stage", value: string) {
    const params = new URLSearchParams(searchParams.toString());

    if (!value) {
      params.delete(name);
    } else {
      params.set(name, value);
    }

    router.replace(`${pathname}?${params.toString()}`);
  }

  const filteredRecords = useMemo(() => {
    return records.filter((candidate) => {
      const matchesStatus = selectedStatus ? candidate.status === selectedStatus : true;
      const matchesStage = selectedStage ? candidate.stage === selectedStage : true;
      const term = searchText.trim().toLowerCase();
      const matchesSearch = term
        ? candidate.full_name.toLowerCase().includes(term) || candidate.email.toLowerCase().includes(term)
        : true;

      return matchesStatus && matchesStage && matchesSearch;
    });
  }, [records, selectedStatus, selectedStage, searchText]);

  return (
    <main className="mx-auto w-full max-w-6xl px-4 py-8 sm:px-6 lg:px-8">
      {created ? (
        <p className="mb-4 rounded-lg bg-emerald-50 px-4 py-3 text-sm font-medium text-emerald-700">
          Candidatura registrada correctamente.
        </p>
      ) : null}

      <section className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm">
        <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
          <div>
            <p className="text-xs font-semibold uppercase tracking-widest text-cyan-700">TrackFlow Tech</p>
            <h1 className="mt-1 text-2xl font-bold text-slate-900">Talent Pipeline Tracker</h1>
            <p className="mt-1 text-sm text-slate-600">Gestión interna para candidaturas de Asistente de Dirección - Zaragoza.</p>
          </div>
          <Link
            href="/candidates/new"
            className="inline-flex w-fit items-center rounded-lg bg-cyan-600 px-4 py-2 text-sm font-semibold text-white transition hover:bg-cyan-500"
          >
            Nueva candidatura
          </Link>
        </div>

        <div className="mt-6 grid gap-3 md:grid-cols-4">
          <div className="md:col-span-2">
            <label htmlFor="search" className="mb-1 block text-sm font-medium text-slate-700">
              Buscar por nombre o email
            </label>
            <input
              id="search"
              value={searchText}
              onChange={(event) => setSearchText(event.target.value)}
              placeholder="Ej: maria@correo.com"
              className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm text-slate-900 focus:border-cyan-500 focus:outline-none"
            />
          </div>

          <div>
            <label htmlFor="statusFilter" className="mb-1 block text-sm font-medium text-slate-700">
              Estado
            </label>
            <select
              id="statusFilter"
              value={selectedStatus}
              onChange={(event) => updateQueryParam("status", event.target.value)}
              className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm text-slate-900 focus:border-cyan-500 focus:outline-none"
            >
              <option value="">Todos</option>
              {STATUS_OPTIONS.map((status) => (
                <option key={status.value} value={status.value}>
                  {status.label}
                </option>
              ))}
            </select>
          </div>

          <div>
            <label htmlFor="stageFilter" className="mb-1 block text-sm font-medium text-slate-700">
              Etapa
            </label>
            <select
              id="stageFilter"
              value={selectedStage}
              onChange={(event) => updateQueryParam("stage", event.target.value)}
              className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm text-slate-900 focus:border-cyan-500 focus:outline-none"
            >
              <option value="">Todas</option>
              {STAGE_OPTIONS.map((stage) => (
                <option key={stage.value} value={stage.value}>
                  {stage.label}
                </option>
              ))}
            </select>
          </div>
        </div>
      </section>

      <section className="mt-6 rounded-2xl border border-slate-200 bg-white shadow-sm">
        {isLoading ? <p className="px-6 py-8 text-sm text-slate-600">Cargando candidaturas...</p> : null}
        {error ? <p className="px-6 py-8 text-sm text-rose-700">{error}</p> : null}

        {!isLoading && !error ? (
          <>
            <div className="border-b border-slate-200 px-6 py-4 text-sm text-slate-600">
              Mostrando {filteredRecords.length} de {records.length} candidaturas
            </div>

            {filteredRecords.length === 0 ? (
              <p className="px-6 py-10 text-sm text-slate-600">No hay candidaturas que coincidan con los filtros actuales.</p>
            ) : (
              <ul className="divide-y divide-slate-200">
                {filteredRecords.map((candidate) => (
                  <li key={candidate.id} className="px-6 py-4">
                    <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
                      <div>
                        <p className="text-sm font-semibold text-slate-900">{candidate.full_name}</p>
                        <p className="text-sm text-slate-600">{candidate.position}</p>
                        <p className="mt-1 text-xs text-slate-500">{candidate.email}</p>
                      </div>

                      <div className="flex flex-wrap items-center gap-2">
                        <StatusBadge status={candidate.status} />
                        <StageBadge stage={candidate.stage} />
                        <Link
                          href={`/candidates/${candidate.id}`}
                          className="rounded-lg border border-slate-300 px-3 py-1.5 text-xs font-semibold text-slate-700 transition hover:border-cyan-400 hover:text-cyan-700"
                        >
                          Ver detalle
                        </Link>
                      </div>
                    </div>
                  </li>
                ))}
              </ul>
            )}
          </>
        ) : null}
      </section>
    </main>
  );
}

export default function HomePage() {
  return (
    <Suspense fallback={<main className="mx-auto w-full max-w-6xl px-4 py-8 sm:px-6 lg:px-8">Cargando...</main>}>
      <HomePageContent />
    </Suspense>
  );
}
